use std::collections::BTreeMap;

fn main() {
    let text = "hello world wonderful world";
    let mut counts = BTreeMap::new();
    for word in text.split_whitespace() {
        let count = counts.entry(word).or_insert(0);
        *count += 1;
    }
    println!("{counts:?}");

    let mut scores = BTreeMap::new();
    scores.insert("Blue", 10);
    scores.entry("Yellow").or_insert(50);
    scores.entry("Blue").or_insert(50);   // Blue exists: unchanged
    let old = scores.insert("Blue", 25);  // overwrite
    println!("{scores:?}, old Blue was {old:?}");
}

use std::collections::{BTreeSet, HashSet, VecDeque};

fn main() {
    let words = ["b", "a", "c", "a", "b"];
    let unique: BTreeSet<&str> = words.iter().copied().collect();
    println!("{unique:?}");

    let mut seen = HashSet::new();
    let first_repeat = words.iter().find(|w| !seen.insert(**w));
    println!("first repeated: {first_repeat:?}");

    let mut queue = VecDeque::new();
    queue.push_back("first");
    queue.push_back("second");
    queue.push_front("urgent");
    println!("{:?} then {:?}", queue.pop_front(), queue.pop_front());
}

